extends Node

const GUARD_PATH := "user://hayat_tounes_session_guard.json"
const TEMP_PATH := "user://hayat_tounes_session_guard.tmp"
const BACKUP_PATH := "user://hayat_tounes_session_guard.backup.json"
const BACKUP_TEMP_PATH := "user://hayat_tounes_session_guard.backup.tmp"
const SCHEMA_VERSION := 1
const MAX_GUARD_BYTES := 64 * 1024
const CRASH_LOOP_THRESHOLD := 2
const CRASH_WINDOW_SECONDS := 900

var session_id := ""
var started_unix := 0
var previous_session_unclean := false
var crash_count := 0
var safe_mode := false
var recovery_reason := "none"
var last_error := ""
var marker_source := "none"

func _ready() -> void:
    process_mode = Node.PROCESS_MODE_ALWAYS
    started_unix = int(Time.get_unix_time_from_system())
    session_id = "%s-%s" % [started_unix, randi()]

    var previous := _read_previous_guard()
    var evaluation := evaluate_previous_marker(previous, started_unix)
    previous_session_unclean = bool(evaluation.get("previous_session_unclean", false))
    crash_count = int(evaluation.get("crash_count", 0))
    safe_mode = bool(evaluation.get("safe_mode", false))
    recovery_reason = str(evaluation.get("reason", "none"))

    if marker_source == "backup":
        recovery_reason = "guard_backup_recovered:%s" % recovery_reason

    # If neither primary nor backup can be trusted, fail closed for this session
    # without overwriting the user's persisted quality preference.
    if not last_error.is_empty():
        previous_session_unclean = true
        safe_mode = true
        recovery_reason = "guard_primary_and_backup_unreadable"

    if safe_mode:
        SettingsService.set_quality_mode("LOW", false)

    _write_marker("running")
    RuntimeDiagnostics.note_session_guard(
        previous_session_unclean,
        crash_count,
        safe_mode,
        recovery_reason,
        marker_source
    )

func evaluate_previous_marker(marker: Dictionary, now_unix: int) -> Dictionary:
    if marker.is_empty():
        return {
            "previous_session_unclean": false,
            "crash_count": 0,
            "safe_mode": false,
            "reason": "none"
        }

    var status := str(marker.get("status", "unknown"))
    if status != "running":
        return {
            "previous_session_unclean": false,
            "crash_count": 0,
            "safe_mode": false,
            "reason": "previous_%s" % status
        }

    var updated_unix := int(marker.get("updated_unix", 0))
    var previous_crash_count := maxi(0, int(marker.get("crash_count", 0)))
    var age := now_unix - updated_unix
    var within_window := updated_unix > 0 and age >= 0 and age <= CRASH_WINDOW_SECONDS
    var next_crash_count := previous_crash_count + 1 if within_window else 1
    var should_safe_mode := next_crash_count >= CRASH_LOOP_THRESHOLD
    return {
        "previous_session_unclean": true,
        "crash_count": next_crash_count,
        "safe_mode": should_safe_mode,
        "reason": "crash_loop" if should_safe_mode else "unclean_previous_session"
    }

func mark_suspended() -> bool:
    return _write_marker("suspended")

func mark_resumed() -> bool:
    return _write_marker("running")

func mark_clean_shutdown(reason: String = "clean_shutdown") -> bool:
    crash_count = 0
    recovery_reason = reason
    return _write_marker("clean")

func session_state() -> Dictionary:
    return {
        "session_id": session_id,
        "started_unix": started_unix,
        "previous_session_unclean": previous_session_unclean,
        "crash_count": crash_count,
        "safe_mode": safe_mode,
        "recovery_reason": recovery_reason,
        "marker_source": marker_source,
        "last_error": last_error
    }

func _read_previous_guard() -> Dictionary:
    last_error = ""
    marker_source = "none"

    var primary := _read_marker_file(GUARD_PATH)
    if bool(primary.get("ok", false)):
        marker_source = "primary"
        return primary.get("marker", {})

    var backup := _read_marker_file(BACKUP_PATH)
    if bool(backup.get("ok", false)):
        marker_source = "backup"
        return backup.get("marker", {})

    var primary_exists := bool(primary.get("exists", false))
    var backup_exists := bool(backup.get("exists", false))
    if primary_exists or backup_exists:
        last_error = "guard_no_valid_copy:primary=%s:backup=%s" % [
            str(primary.get("error", "missing")),
            str(backup.get("error", "missing"))
        ]
    return {}

func _read_marker_file(path: String) -> Dictionary:
    if not FileAccess.file_exists(path):
        return {"ok": false, "exists": false, "error": "missing", "marker": {}}
    var file := FileAccess.open(path, FileAccess.READ)
    if file == null:
        return {"ok": false, "exists": true, "error": "open_failed", "marker": {}}
    var length := file.get_length()
    if length < 0 or length > MAX_GUARD_BYTES:
        return {"ok": false, "exists": true, "error": "file_too_large", "marker": {}}
    var json := JSON.new()
    if json.parse(fi

le.get_as_text()) != OK:
        return {"ok": false, "exists": true, "error": "invalid_json", "marker": {}}
    var parsed = json.data
    if typeof(parsed) != TYPE_DICTIONARY:
        return {"ok": false, "exists": true, "error": "invalid_json", "marker": {}}
    if int(parsed.get("schema_version", -1)) != SCHEMA_VERSION:
        return {"ok": false, "exists": true, "error": "schema_unsupported", "marker": {}}
    var status := str(parsed.get("status", ""))
    if status not in ["running", "suspended", "clean"]:
        return {"ok": false, "exists": true, "error": "status_invalid", "marker": {}}
    if int(parsed.get("updated_unix", 0)) <= 0:
        return {"ok": false, "exists": true, "error": "timestamp_invalid", "marker": {}}
    return {"ok": true, "exists": true, "error": "", "marker": parsed}

func _write_marker(status: String) -> bool:
    if status not in ["running", "suspended", "clean"]:
        last_error = "guard_status_invalid"
        return false

    last_error = ""
    var payload := {
        "schema_version": SCHEMA_VERSION,
        "build_version": str(ProjectSettings.get_setting("application/config/version", "unknown")),
        "session_id": session_id,
        "status": status,
        "started_unix": started_unix,
        "updated_unix": int(Time.get_unix_time_from_system()),
        "crash_count": crash_count,
        "safe_mode": safe_mode,
        "recovery_reason": recovery_reason
    }
    var encoded := JSON.stringify(payload, "  ")
    if encoded.to_utf8_buffer().size() > MAX_GUARD_BYTES:
        last_error = "guard_too_large"
        return false
    if not _write_temp_file(TEMP_PATH, encoded):
        last_error = "guard_temp_write_failed"
        return false

    # Transactional replace: keep the last committed primary as rollback material
    # until the new primary has been promoted successfully.
    var moved_primary := false
    if FileAccess.file_exists(GUARD_PATH):
        if FileAccess.file_exists(BACKUP_PATH):
            var remove_backup := DirAccess.remove_absolute(ProjectSettings.globalize_path(BACKUP_PATH))
            if remove_backup != OK:
                last_error = "guard_backup_remove_failed:%s" % remove_backup
                _remove_if_exists(TEMP_PATH)
                return false
        var move_old := DirAccess.rename_absolute(
            ProjectSettings.globalize_path(GUARD_PATH),
            ProjectSettings.globalize_path(BACKUP_PATH)
        )
        if move_old != OK:
            last_error = "guard_primary_to_backup_failed:%s" % move_old
            _remove_if_exists(TEMP_PATH)
            return false
        moved_primary = true

    var promote := DirAccess.rename_absolute(
        ProjectSettings.globalize_path(TEMP_PATH),
        ProjectSettings.globalize_path(GUARD_PATH)
    )
    if promote != OK:
        last_error = "guard_promote_failed:%s" % promote
        if moved_primary and FileAccess.file_exists(BACKUP_PATH):
            var rollback := DirAccess.rename_absolute(
                ProjectSettings.globalize_path(BACKUP_PATH),
                ProjectSettings.globalize_path(GUARD_PATH)
            )
            if rollback != OK:
                last_error += ":rollback_failed:%s" % rollback
        _remove_if_exists(TEMP_PATH)
        return false

    # Refresh the redundant copy after primary commit. Primary remains authoritative;
    # failure here is observable but does not invalidate the committed lifecycle state.
    if not _write_temp_file(BACKUP_TEMP_PATH, encoded):
        last_error = "guard_backup_temp_write_failed"
        return true
    if FileAccess.file_exists(BACKUP_PATH):
        var remove_old_backup := DirAccess.remove_absolute(ProjectSettings.globalize_path(BACKUP_PATH))
        if remove_old_backup != OK:
            last_error = "guard_backup_refresh_remove_failed:%s" % remove_old_backup
            _remove_if_exists(BACKUP_TEMP_PATH)
            return true
    var promote_backup := DirAccess.rename_absolute(
        ProjectSettings.globalize_path(BACKUP_TEMP_PATH),
        ProjectSettings.globalize_path(BACKUP_PATH)
    )
    if promote_backup != OK:
        last_error = "guard_backup_refresh_promote_failed:%s" % promote_backup
        _remove_if_exists(BACKUP_TEMP_PATH)
    return true

func _write_temp_file(path: String, encoded: String) -> bool:
    var file := FileAccess.open(path, FileAccess.WRITE)
    if file == null:
        return false
    file.store_string(encoded)
    file.flush()
    var ok := file.get_error() == OK
    file.close()
    return ok

func _remove_if_exists(path: String) -> void:
    if FileAccess.file_exists(path):
        DirAccess.remove_absolute(ProjectSettings.globalize_path(path))

func _notification(what: int) -> void:
    if what == NOTIFICATION_APPLICATION_PAUSED:
        mark_suspended()
    elif what == NOTIFICATION_APPLICATION_RESUMED:
        mark_resumed()
    elif what == NOTIFICATION_WM_CLOSE_REQUEST:
        mark_clean_shutdown("window_close")

